def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = min((v for v in counts if v != background), key=lambda v: counts[v])

    out = [row[:] for row in grid]

    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
